import { CodegenError } from './model.ts';
import type { ContentType, Field, Trait, TypeModel } from './model.ts';

export interface GeneratedFile
{
    /** Relative to the output directory. */
    readonly path: string;

    readonly contents: string;
}

export interface Generated
{
    readonly files: readonly GeneratedFile[];

    /** Things to tell whoever ran the generator. Never fatal. */
    readonly warnings: readonly string[];
}

/** How every generated file starts, so a later run knows which files are its own to remove. */
export const GENERATED_MARK = '// Generated by @coho-cms/codegen from the Coho type model.';

const HEADER = `${GENERATED_MARK} Do not edit: run \`coho-codegen generate\`.`;

const INDENT = '    ';

/**
 * Names the generated code defines or re-exports, and `Index`, whose file would be
 * `index.ts`'s on a case-insensitive file system. A content type whose name would be
 * one of these is given `Entry` after it instead, so no project's types can shadow them.
 */
const RESERVED_TYPE_NAMES = new Set(['AnyEntry', 'Coho', 'Index', 'Linked', 'Unresolved', 'RepeaterItem']);

/** The untyped reads on `Coho`. A content type with one of these slugs reads as `<slug>Type`. */
const RESERVED_MEMBERS = new Set(['bySlug', 'byId', 'byIds']);

/**
 * The TypeScript for a type model: a file per content type holding its interface,
 * such as `BlogPost.ts`, one per component type, such as `Citation.ts`, and `index.ts`,
 * which exports them all with the content types' union, the shape the runtime hydrates
 * with, the model's source, and `createCoho`.
 *
 * A pure function of the model, so the same model always gives the same bytes and a
 * drift check can compare them. Nothing about the generator's own version is
 * written, for the same reason.
 */
export function generate(model: TypeModel): Generated
{
    const warnings: string[] = [];
    for (const warning of model.warnings ?? []) warnings.push(`${warning.type}.${warning.field}: ${warning.message}`);
    if (!model.source.immutable)
    {
        warnings.push(`Generated from '${model.source.ref}', a branch: its types can change. Release builds should name a tag.`);
    }

    const types = Object.keys(model.types).sort().map((slug) => model.types[slug] as ContentType);
    // Since type model 1.2. Content and component types share one slug namespace, so
    // they share one set of names too.
    const components = Object.keys(model.components ?? {}).sort().map((slug) => model.components?.[slug] as ContentType);
    // Since type model 1.4: a trait is an interface every type with it extends. Traits
    // share the slug namespace too, and with it the names.
    const traits = Object.keys(model.traits ?? {}).sort().map((slug) => model.traits?.[slug] as Trait);
    const names = interfaceNames([...types, ...components, ...traits], warnings);
    const nameOf = (slug: string): string => names.get(slug) ?? 'runtime.HydratedEntry';
    // Since type model 1.3: delivery lists a type with its descendants, so a read or a
    // link of a base type is any type in its family.
    const family = families([...types, ...components], names, warnings);
    // Untyped items remain where a repeater names no component on the ref.
    const usesRepeaters = [...types, ...components].some((type) => type.fields.some(untypedRepeater));

    const files = [
        indexFile(model, types, components, traits, nameOf, family, usesRepeaters, warnings),
        ...types.map((type) => typeFile(type, names, nameOf, family, warnings)),
        ...components.map((component) => typeFile(component, names, nameOf, family, warnings, 'component')),
        ...traits.map((trait) => traitFile(trait, names, nameOf, family, warnings)),
    ];
    if (usesRepeaters) files.push(repeaterFile());
    sameFileCheck(files);
    return { files, warnings };
}

/** `index.ts`: every type, and what reads them. */
function indexFile(
    model: TypeModel,
    types: readonly ContentType[],
    components: readonly ContentType[],
    traits: readonly Trait[],
    nameOf: (slug: string) => string,
    family: Families,
    usesRepeaters: boolean,
    warnings: string[],
): GeneratedFile
{
    // Each name with the file it is in: a family's alias is in its base type's file.
    const exported: [string, string][] = [];
    for (const type of [...types, ...components])
    {
        exported.push([nameOf(type.slug), nameOf(type.slug)]);
        if (family.has(type.slug)) exported.push([family.alias(type.slug), nameOf(type.slug)]);
    }
    for (const trait of traits) exported.push([nameOf(trait.slug), nameOf(trait.slug)]);
    exported.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    if (usesRepeaters) exported.push(['RepeaterItem', 'RepeaterItem']);
    // An abstract type has no entries of its own, so it is not one of the types an entry is.
    const concrete = types.filter((type) => type.abstract !== true);
    const imported = new Map<string, Set<string>>();
    const use = (name: string, file: string): void =>
    {
        (imported.get(file) ?? imported.set(file, new Set()).get(file))?.add(name);
    };
    for (const type of concrete) use(nameOf(type.slug), nameOf(type.slug));
    for (const type of types) use(family.target(type.slug), nameOf(type.slug));

    const kind = model.source.immutable ? 'a tag' : 'a branch, whose types can change';
    const out = [
        HEADER,
        `// Project ${model.source.project}, ref ${model.source.ref} (${kind}), schema ${model.source.schemaHash}, type model ${model.irVersion}.`,
        '',
        'import * as runtime from "@coho-cms/delivery";',
        ...[...imported.keys()].sort().map((file) => `import type { ${[...(imported.get(file) ?? [])].sort().join(', ')} } from "./${file}.ts";`),
        '',
        'export { isResolved } from "@coho-cms/delivery";',
        'export type { Linked, Unresolved } from "@coho-cms/delivery";',
        ...exported.map(([name, file]) => `export type { ${name} } from "./${file}.ts";`),
        '',
        '/** Any content type on this ref. Switch on `_type` to narrow it. */',
        `export type AnyEntry = ${concrete.length === 0 ? 'never' : concrete.map((type) => nameOf(type.slug)).join(' | ')};`,
        '',
        ...shapeOf(concrete, components, family),
        '',
        ...sourceOf(model),
        '',
        ...client(types, nameOf, family, warnings),
    ];
    return { path: 'index.ts', contents: `${out.join('\n')}\n` };
}

/**
 * One content or component type's interface, importing the types it links to and the
 * components its repeaters hold. A component is a repeater item, so it extends
 * `ItemBase`, with an `_id` and `_type`, where a content type extends `EntryBase`.
 */
function typeFile(
    type: ContentType,
    names: ReadonlyMap<string, string>,
    nameOf: (slug: string) => string,
    family: Families,
    warnings: string[],
    kind: 'content' | 'component' = 'content',
): GeneratedFile
{
    const name = nameOf(type.slug);
    // Each name this file uses, by the file it is in. Not its own, which a type that
    // links to itself, or a component that holds itself (type model 1.6), names.
    const linked = new Map<string, Set<string>>();
    const use = (other: string, file: string): void =>
    {
        if (file !== name) (linked.get(file) ?? linked.set(file, new Set()).get(file))?.add(other);
    };
    for (const field of type.fields)
    {
        if (untypedRepeater(field)) use('RepeaterItem', 'RepeaterItem');
        // A target or component not on the ref is untyped, with nothing to import.
        for (const slug of field.kind === 'reference' || field.kind === 'repeater' ? (field.of ?? []) : [])
        {
            if (names.has(slug)) use(family.target(slug), nameOf(slug));
        }
    }
    // A family's alias lists every concrete type in it, from their own files.
    const members = family.has(type.slug) ? family.members(type.slug) : [];
    for (const member of members) use(nameOf(member), nameOf(member));
    // Since type model 1.4: every trait it has, so code written against a trait takes it.
    const traits = (type.traits ?? []).filter((slug) => names.has(slug)).map(nameOf);
    for (const trait of traits) use(trait, trait);
    const base = kind === 'component' ? 'ItemBase' : 'EntryBase';
    // An abstract type's entries are its descendants', so its `_type` is any of theirs.
    const discriminant = type.abstract === true && members.length > 0
        ? members.map((member) => JSON.stringify(member)).join(' | ')
        : JSON.stringify(type.slug);

    const out = [
        HEADER,
        '',
        'import type * as runtime from "@coho-cms/delivery";',
        ...[...linked.keys()].sort().map((file) => `import type { ${[...(linked.get(file) ?? [])].sort().join(', ')} } from "./${file}.ts";`),
        '',
        doc(type.name, [
            kind === 'component' ? 'A repeater item, stored in the entry that holds it.' : '',
            type.extends !== undefined && names.has(type.extends) ? `Extends ${nameOf(type.extends)}, and has every field it has.` : '',
            type.abstract === true ? `Abstract: ${kind === 'component' ? 'an item' : 'an entry'} is one of the types that extend it.` : '',
            traits.length > 0 ? `Has the trait${traits.length === 1 ? '' : 's'} ${listed(traits)}.` : '',
        ].filter((part) => part !== '').join(' ')),
        `export interface ${name} extends ${[`runtime.${base}<${discriminant}>`, ...traits].join(', ')}`,
        '{',
    ];
    for (const [i, field] of type.fields.entries())
    {
        // Every field is documented, so each is its own paragraph.
        if (i > 0) out.push('');
        out.push(`${INDENT}${doc(field.name, note(field))}`);
        const optional = field.presence === 'always' ? '' : '?';
        out.push(`${INDENT}readonly ${field.id}${optional}: ${fieldType(type, field, family, warnings)};`);
    }
    out.push('}');
    if (members.length > 0)
    {
        out.push(
            '',
            doc(`A ${type.name} of any kind: ${members.map(nameOf).join(', ')}`, 'Switch on `_type` to narrow it.'),
            `export type ${family.alias(type.slug)} = ${members.map(nameOf).join(' | ')};`,
        );
    }
    return { path: `${name}.ts`, contents: `${out.join('\n')}\n` };
}

/** `A`, `A and B`, or `A, B, and C`. */
function listed(names: readonly string[]): string
{
    if (names.length <= 2) return names.join(' and ');
    return `${names.slice(0, -1).join(', ')}, and ${names[names.length - 1]}`;
}

/**
 * A trait (type model 1.4): an interface of the fields it declares, which every type that
 * has it extends. Each type still declares those fields itself, as it has them, which may
 * be tighter than the trait's; TypeScript checks that each is. So a function that takes a
 * `Seo` takes an entry of any type with the trait.
 */
function traitFile(trait: Trait, names: ReadonlyMap<string, string>, nameOf: (slug: string) => string, family: Families, warnings: string[]): GeneratedFile
{
    const name = nameOf(trait.slug);
    const linked = new Map<string, Set<string>>();
    for (const field of trait.fields)
    {
        if (untypedRepeater(field)) (linked.get('RepeaterItem') ?? linked.set('RepeaterItem', new Set()).get('RepeaterItem'))?.add('RepeaterItem');
        for (const slug of field.kind === 'reference' || field.kind === 'repeater' ? (field.of ?? []) : [])
        {
            if (names.has(slug)) (linked.get(nameOf(slug)) ?? linked.set(nameOf(slug), new Set()).get(nameOf(slug)))?.add(family.target(slug));
        }
    }
    const asType: ContentType = { slug: trait.slug, name: trait.name, version: trait.version, fields: trait.fields };
    const uses = trait.fields.some((field) => /runtime\./.test(fieldType(asType, field, family, [])));
    const out = [
        HEADER,
        '',
        ...(uses ? ['import type * as runtime from "@coho-cms/delivery";'] : []),
        ...[...linked.keys()].sort().map((file) => `import type { ${[...(linked.get(file) ?? [])].sort().join(', ')} } from "./${file}.ts";`),
        ...(uses || linked.size > 0 ? [''] : []),
        doc(trait.name, 'A trait: fields that every type with it has. Take it to accept an entry of any of them.'),
        `export interface ${name}`,
        '{',
    ];
    for (const [i, field] of trait.fields.entries())
    {
        if (i > 0) out.push('');
        out.push(`${INDENT}${doc(field.name, note(field))}`);
        const optional = field.presence === 'always' ? '' : '?';
        out.push(`${INDENT}readonly ${field.id}${optional}: ${fieldType(asType, field, family, warnings)};`);
    }
    out.push('}');
    return { path: `${name}.ts`, contents: `${out.join('\n')}\n` };
}

/**
 * Type inheritance (type model 1.3). Delivery lists a type with its descendants, and a
 * link or an item of a base type may be any of them, so a base type has a **family**:
 * the concrete types an entry or item of it can be, itself unless abstract and every
 * concrete descendant. A type with descendants is read and linked as its family's alias,
 * `AnyPage`; a type with none, as itself. Interfaces stay flattened, as the model is,
 * so no subtype has to redeclare the `_type` it narrows.
 */
interface Families
{
    /** Whether [slug] has descendants, and so a family alias. */
    has(slug: string): boolean;

    /** The concrete types in [slug]'s family, sorted by slug. */
    members(slug: string): readonly string[];

    /** [slug]'s family alias, `AnyPage`. */
    alias(slug: string): string;

    /** How a read or a link of [slug] is typed: its family's alias, or itself. */
    target(slug: string): string;
}

function families(types: readonly ContentType[], names: ReadonlyMap<string, string>, warnings: string[]): Families
{
    const bySlug = new Map(types.map((type) => [type.slug, type]));
    const below = new Map<string, string[]>();
    for (const type of types)
    {
        // Each ancestor on the ref, cycle-guarded: the server refuses a cycle, so this only stops a broken file.
        const seen = new Set([type.slug]);
        let parent = type.extends;
        while (parent !== undefined && bySlug.has(parent) && !seen.has(parent))
        {
            seen.add(parent);
            (below.get(parent) ?? below.set(parent, []).get(parent))?.push(type.slug);
            parent = bySlug.get(parent)?.extends;
        }
    }
    const taken = new Set(names.values());
    const aliases = new Map<string, string>();
    for (const slug of [...below.keys()].sort())
    {
        const name = names.get(slug) ?? slug;
        let alias = `Any${name}`;
        if (taken.has(alias) || RESERVED_TYPE_NAMES.has(alias))
        {
            warnings.push(`The types that extend '${slug}' are named ${name}Family, because ${alias} is taken.`);
            alias = `${name}Family`;
        }
        if (taken.has(alias)) throw new CodegenError(`The family of '${slug}' would be named ${alias}, which a type already is; rename one of them`);
        taken.add(alias);
        aliases.set(slug, alias);
    }
    const members = (slug: string): readonly string[] =>
        [slug, ...(below.get(slug) ?? [])].filter((each) => bySlug.get(each)?.abstract !== true).sort();
    return {
        has: (slug) => aliases.has(slug) && members(slug).length > 0,
        members,
        alias: (slug) => aliases.get(slug) ?? names.get(slug) ?? slug,
        target: (slug) => (aliases.has(slug) && members(slug).length > 0 ? (aliases.get(slug) ?? slug) : (names.get(slug) ?? 'runtime.HydratedEntry')),
    };
}

function repeaterFile(): GeneratedFile
{
    const out = [
        HEADER,
        '',
        '/** An item of a repeater whose component types are not on this ref, so its fields are not typed. */',
        'export type RepeaterItem = { readonly _id: string; readonly _type?: string; readonly [field: string]: unknown };',
    ];
    return { path: 'RepeaterItem.ts', contents: `${out.join('\n')}\n` };
}

/** Two paths a case-insensitive file system, such as macOS's or Windows', would write to one file. */
function sameFileCheck(files: readonly GeneratedFile[]): void
{
    const seen = new Map<string, string>();
    for (const { path } of files)
    {
        const other = seen.get(path.toLowerCase());
        if (other !== undefined) throw new CodegenError(`${other} and ${path} would be one file on a case-insensitive file system; rename one of their types`);
        seen.set(path.toLowerCase(), path);
    }
}

/** `blogPost` becomes `BlogPost`. Slugs start lowercase, so no two types share a name. */
function interfaceNames(types: readonly ContentType[], warnings: string[]): Map<string, string>
{
    const names = new Map<string, string>();
    const taken = new Set<string>();
    for (const type of types)
    {
        let name = type.slug.charAt(0).toUpperCase() + type.slug.slice(1);
        if (RESERVED_TYPE_NAMES.has(name))
        {
            warnings.push(`Type '${type.slug}' is named ${name}Entry, because ${name} is taken by the generated code.`);
            name = `${name}Entry`;
        }
        if (taken.has(name)) throw new CodegenError(`Two types would both be named ${name}; rename one of them`);
        taken.add(name);
        names.set(type.slug, name);
    }
    return names;
}

/** The TypeScript type of one field's value, following the type model's mapping rules. */
function fieldType(type: ContentType, field: Field, family: Families, warnings: string[]): string
{
    switch (field.kind)
    {
        case 'text':
        case 'longText':
        case 'datetime':
            return 'string';
        case 'number':
        case 'integer':
            return 'number';
        case 'boolean':
            return 'boolean';
        case 'json':
            return 'unknown';
        case 'choice':
            return choices(field);
        case 'multichoice':
            return `readonly (${choices(field)})[]`;
        case 'reference': {
            // An empty `of` means the target's type is not on this ref: an untyped entry.
            const targets = field.of ?? [];
            // A base type links to any type in its family (type model 1.3).
            const target = targets.length === 0 ? 'runtime.HydratedEntry' : [...new Set(targets.map(family.target))].join(' | ');
            return field.many ? `readonly runtime.Linked<${target}>[]` : `runtime.Linked<${target}>`;
        }
        case 'asset': {
            // Embedded by delivery, never a link to follow. One that is gone on the ref
            // is null, required or not, so a single asset is always nullable; in a many
            // field a gone asset is left out (coho-sdk-spec, "Asset fields").
            const asset = imageOnly(field) ? 'runtime.ImageAsset' : 'runtime.Asset';
            return field.many ? `readonly ${asset}[]` : `${asset} | null`;
        }
        case 'list': {
            // Since type model 1.5: plain values, never links, so the runtime passes it
            // through as delivery sent it. A localized one is the locale's array.
            const item = listItem(field);
            if (item === undefined)
            {
                warnings.push(`${type.slug}.${field.id} is a list of '${String(field.item)}', which this generator does not know; its values are typed unknown. Upgrade @coho-cms/codegen.`);
                return 'readonly unknown[]';
            }
            return `readonly ${item}[]`;
        }
        case 'repeater': {
            // A union on `_type` of the components on the ref. The runtime leaves out
            // an item of any other component (`shape`'s `items`), so the union is never
            // wrong about what it holds. Since type model 1.6 a component's repeater is
            // typed the same way, and one that holds itself is a recursive type.
            const components = field.of ?? [];
            if (components.length === 0) return 'readonly RepeaterItem[]';
            const kinds = [...new Set(components.map(family.target))];
            const union = kinds.join(' | ');
            return kinds.length === 1 ? `readonly ${union}[]` : `readonly (${union})[]`;
        }
        default:
            warnings.push(`${type.slug}.${field.id} is a '${field.kind}', which this generator does not know; it is typed unknown. Upgrade @coho-cms/codegen.`);
            return 'unknown';
    }
}

/**
 * A choice's values, and any other string: content may hold a value added after this
 * code was generated, and that must not stop it compiling against the new content.
 */
function choices(field: Field): string
{
    return [...(field.values ?? []).map((value) => JSON.stringify(value)), '(string & {})'].join(' | ');
}

/** The TypeScript type of each of a list's values, or undefined for an item kind this generator does not know. */
function listItem(field: Field): string | undefined
{
    switch (field.item)
    {
        case 'text':
        case 'datetime':
            return 'string';
        case 'integer':
        case 'number':
            return 'number';
        default:
            return undefined;
    }
}

/** A repeater that names no component on the ref, whose items are typed as {@link repeaterFile}'s. */
function untypedRepeater(field: Field): boolean
{
    return field.kind === 'repeater' && (field.of ?? []).length === 0;
}

/** A repeater that names components on the ref, whose items the runtime keeps only if it lists them. */
function typedRepeater(field: Field): boolean
{
    return field.kind === 'repeater' && !untypedRepeater(field);
}

/** Whether every file the field accepts is a raster image, which always has dimensions. */
function imageOnly(field: Field): boolean
{
    const accept = field.accept ?? [];
    return accept.length > 0 && accept.every((type) => RASTER_IMAGES.has(type));
}

const RASTER_IMAGES: ReadonlySet<string> = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'image/avif', 'image/heic']);

function note(field: Field): string
{
    const notes: string[] = [];
    if (field.kind === 'asset' && (field.accept ?? []).length > 0) notes.push(`Accepts ${(field.accept ?? []).join(', ')}.`);
    if (field.kind === 'longText' && field.textFormat === 'markdown') notes.push('Markdown.');
    if (field.kind === 'longText' && field.textFormat === 'html') notes.push('HTML.');
    if (field.kind === 'datetime') notes.push('An ISO 8601 date and time.');
    if (field.kind === 'list')
    {
        if (field.item === 'datetime') notes.push('Each an ISO 8601 date and time.');
        if (field.min !== undefined || field.max !== undefined) notes.push(`${counted(field.min, field.max)}.`);
        // An empty list is a value: the locale has none, where an untranslated one leaves the field out.
        if (field.localized) notes.push('The locale\'s own list, empty when it has none.');
    }
    if (field.localized) notes.push('Absent where the locale has no translation.');
    return notes.join(' ');
}

/** How many values a list holds: `At least 1 value`, `At most 5 values`, or `1 to 5 values`. */
function counted(min: number | undefined, max: number | undefined): string
{
    const values = (count: number): string => `${count} value${count === 1 ? '' : 's'}`;
    if (min !== undefined && max !== undefined) return min === max ? `Exactly ${values(min)}` : `${min} to ${values(max)}`;
    return min !== undefined ? `At least ${values(min)}` : `At most ${values(max ?? 0)}`;
}

/** A one-line doc comment. Names are content, so a comment's end inside one is broken up. */
function doc(name: string, note: string): string
{
    const text = [name.replace(/\s+/g, ' ').trim(), note].filter((part) => part !== '').join('. ').replace(/\*\//g, '*\\/');
    return `/** ${text} */`;
}

/**
 * The runtime's shape: each concrete content type's links, the fields it always has,
 * and the components each repeater holds, then, since type model 1.6, the components
 * each component's repeaters hold, so items are filtered at every level. A component
 * may hold itself, so each is listed once, by slug, and never walked.
 */
function shapeOf(types: readonly ContentType[], components: readonly ContentType[], family: Families): string[]
{
    const doc = '/** What the runtime needs to hydrate each type, and each component with repeaters: its links, the fields it always has, and the components each repeater holds. */';
    // An item is always of a concrete component, and only its repeaters are checked.
    const holders = components.filter((component) => component.abstract !== true && component.fields.some(typedRepeater));
    if (types.length === 0 && holders.length === 0) return [doc, 'export const shape: runtime.Shape = {};'];
    const lines = [doc, 'export const shape: runtime.Shape = {'];
    for (const type of types)
    {
        // A list (type model 1.5) holds plain values, so it is neither a link nor items.
        const links = type.fields
            .filter((field) => field.kind === 'reference')
            .map((field) => `${field.id}: ${JSON.stringify(field.many ? 'many' : 'one')}`);
        const always = type.fields.filter((field) => field.presence === 'always').map((field) => JSON.stringify(field.id));
        const items = itemsOf(type, family);

        const parts: string[] = [];
        if (links.length > 0) parts.push(`links: { ${links.join(', ')} }`);
        if (always.length > 0) parts.push(`always: [${always.join(', ')}]`);
        if (items.length > 0) parts.push(`items: { ${items.join(', ')} }`);
        lines.push(`${INDENT}${type.slug}: {${parts.length === 0 ? '' : ` ${parts.join(', ')} `}},`);
    }
    // Nothing about an item is checked but the items it holds.
    for (const component of holders) lines.push(`${INDENT}${component.slug}: { items: { ${itemsOf(component, family).join(', ')} } },`);
    lines.push('};');
    return lines;
}

/** Each typed repeater's entry in `items`: the field id and the concrete components it holds. */
function itemsOf(type: ContentType, family: Families): string[]
{
    return type.fields
        .filter(typedRepeater)
        // The concrete components: the runtime keeps an item only if its `_type` is listed,
        // and an item of a base component is always one of its family (type model 1.3).
        .map((field) => `${field.id}: [${[...new Set((field.of ?? []).flatMap((slug) => (family.has(slug) ? family.members(slug) : [slug])))].map((slug) => JSON.stringify(slug)).join(', ')}]`);
}

function sourceOf(model: TypeModel): string[]
{
    return [
        '/** Where these types came from, for reporting which release a build was made from. */',
        'export const source = {',
        `${INDENT}project: ${JSON.stringify(model.source.project)},`,
        `${INDENT}ref: ${JSON.stringify(model.source.ref)},`,
        `${INDENT}immutable: ${model.source.immutable},`,
        `${INDENT}schemaHash: ${JSON.stringify(model.source.schemaHash)},`,
        `${INDENT}irVersion: ${JSON.stringify(model.irVersion)},`,
        '} as const;',
    ];
}

function client(types: readonly ContentType[], nameOf: (slug: string) => string, family: Families, warnings: string[]): string[]
{
    const members = new Set<string>();
    const readers = types.map((type) =>
    {
        let member = type.slug;
        if (RESERVED_MEMBERS.has(member))
        {
            warnings.push(`Type '${type.slug}' is read as coho.${member}Type, because coho.${member} is the untyped read.`);
            member = `${member}Type`;
        }
        if (members.has(member)) throw new CodegenError(`Two types would both be read as coho.${member}; rename one of them`);
        members.add(member);
        const sortable = type.fields.filter((field) => field.sortable).map((field) => JSON.stringify(field.id));
        // A type's read lists its descendants too (type model 1.3), so it reads its family.
        const generic = `${family.target(type.slug)}, ${sortable.length === 0 ? 'never' : sortable.join(' | ')}`;
        return { type, member, generic };
    });

    const lines = ['/** Typed reads of every content type, on the ref and in the locale the config names. */', 'export interface Coho', '{'];
    // Every member is documented, so each is its own paragraph.
    for (const { type, member, generic } of readers)
    {
        lines.push(`${INDENT}${doc(type.name, '')}`);
        lines.push(`${INDENT}readonly ${member}: runtime.TypeReader<${generic}>;`);
        lines.push('');
    }
    lines.push(
        `${INDENT}/** The entry with this slug, whatever its type, or null. */`,
        `${INDENT}bySlug(slug: string, options?: runtime.ReadOptions): Promise<AnyEntry | null>;`,
        '',
        `${INDENT}/** The entry with this id, whatever its type, or null. */`,
        `${INDENT}byId(id: string, options?: runtime.ReadOptions): Promise<AnyEntry | null>;`,
        '',
        `${INDENT}/** The entries that exist, sorted by id. Ids not on the ref are left out. */`,
        `${INDENT}byIds(ids: readonly string[], options?: runtime.ReadOptions): Promise<AnyEntry[]>;`,
        '}',
        '',
        '/** A client for these types. The delivery key comes from the app; this library reads no environment. */',
        'export function createCoho(config: runtime.ContentConfig): Coho',
        '{',
        `${INDENT}const content = runtime.createContentClient<AnyEntry>(config, shape);`,
        `${INDENT}return {`,
    );
    for (const { type, member, generic } of readers)
    {
        // A typed read of one entry checks its `_type`, which for a base type is any in its family.
        const kinds = family.has(type.slug) ? `, [${family.members(type.slug).map((slug) => JSON.stringify(slug)).join(', ')}]` : '';
        lines.push(`${INDENT}${INDENT}${member}: content.type<${generic}>(${JSON.stringify(type.slug)}${kinds}),`);
    }
    lines.push(
        `${INDENT}${INDENT}bySlug: content.bySlug,`,
        `${INDENT}${INDENT}byId: content.byId,`,
        `${INDENT}${INDENT}byIds: content.byIds,`,
        `${INDENT}};`,
        '}',
    );
    return lines;
}
